```js
import fs from 'node:fs';
import zlib from 'node:zlib';
import { Transform, pipeline } from 'node:stream/promises';
const upper = new Transform({
  transform(c, e, cb) { cb(null, c.toString().toUpperCase()); },
});
await pipeline(
  fs.createReadStream('in.log'),
  upper,
  zlib.createGzip(),
