```js
import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
import os from 'node:os';
if (isMainThread) {
  const jobs = [1, 2, 3, 4, 5, 6, 7, 8];
  const N = os.cpus().length;
  const run = (job) => new Promise((res, rej) => {
    const w = new Worker(new URL(import.meta.url), { workerData: job });
    w.once('message', res);
    w.once('error', rej);
  });
  const out = [];
  for (let i = 0; i < jobs.length; i += N)
    out.push(...await Promise.all(jobs.slice(i, i + N).map(run)));
  console.log(out);
} else {
  let s = 0;
  for (let i = 0; i < 1e7; i++) s += Math.sqrt(i + workerData);
  parentPort.postMessage(s);
}
```
Satu fail dua peranan (`isMainThread` guard), batch sepadan CPU, result dikumpul tertib. CPU keluar dari loop, I/O kekal di loop.

