```js
import express from 'express';
import client from 'prom-client';
const reg = new client.Registry();
client.collectDefaultMetrics({ register: reg });
const http = new client.Histogram({
  name: 'http_ms', help: 'latency', labelNames: ['route', 'code'],
  buckets: [10, 50, 100, 300, 1000], registers: [reg],
});
const app = express();
app.use((req, res, next) => {
  const t = Date.now();
  res.on('finish', () => http.labels(req.route?.path ?? '?', res.statusCode).observe(Date.now() - t));
  next();
});
app.get('/metrics', async (req, res) => {
  res.set('content-type', reg.contentType);
  res.end(await reg.metrics());
});
```
Histogram (bukan purata!) + label laluan/kod; default metrics USE sumber. Grafana baca `/metrics`, alertmanager ambang — RED setiap endpoint.

